import type { PatenteHistorico } from './Seccion7_6Patentes';

type FilaPatenteMicroempresa = [
  numero: string,
  fecha: string,
  descripcion: string,
  tieneEfectosGenerales: 'Sí' | 'No',
  fechaPublicacion?: string,
  urlPublicacion?: string,
  urlModificacion?: string,
  ultimaActualizacion?: string,
  nombreTitulo?: string
];

const crearPatentesMicroempresa = (
  filas: FilaPatenteMicroempresa[],
  tipoNorma = 'Decretos Exentos',
  enlaceModificacion = 'Sin Modificaciones',
  fechaPublicacionPorDefecto = '03.06.2016, Página Web'
): PatenteHistorico[] =>
  filas.map(([numero, fecha, descripcion, tieneEfectosGenerales, fechaPublicacion = fechaPublicacionPorDefecto, urlPublicacion = '', urlModificacion = '', ultimaActualizacion = 'Sin Modificaciones', nombreTitulo = 'Patente Comercial Micro Empresa Familiar']) => ({
    tipoNorma,
    denominacion: 'Patentes y Permisos',
    nombreTitulo,
    numero,
    fecha,
    fechaPublicacion: fechaPublicacion || '03.06.2016, Página Web',
    tieneEfectosGenerales,
    ultimaActualizacion,
    descripcion,
    urlPublicacion, urlModificacion, enlacePublicacion: 'PDF',
    enlaceModificacion
  }));

